	background(0);
	seed = random(100);
}

function draw() {
	background(0);
	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
	theShader.setUniform("u_x", (1+sin(frameCount/10))/2);
	theShader.setUniform("u_density", pixelDensity());
	theShader.setUniform("u_seed", seed);
	theShader.setUniform("u_time", frameCount/400);
	shader(theShader);
	rect(0,0,width,height);
}

