let vertShader = `

#ifdef GL_ES //for browser or mobile
//can change mediump to either lowp or highp.
precision mediump float;
#endif

// Input:
attribute vec3 aPosition;  //position of the vertex

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);

	// This is a weird behaviour in p5. Need to scale the vertices so they will appear in the right place.
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

	//Output:
  gl_Position = positionVec4;
}`;


// === Tab: frag shader ===
const PI = 3.141592653589793238;

let fragShader = `
#ifdef GL_ES 
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_seed;
uniform float u_time;
uniform float u_density;
uniform vec2 u_mouse;

// Some useful functions
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

//
// Description : GLSL 2D simplex noise function
//      Author : Ian McEwan, Ashima Arts
//  Maintainer : ijm
//     Lastmod : 20110822 (ijm)
//     License :
//  Copyright (C) 2011 Ashima Arts. All rights reserved.
//  Distributed under the MIT License. See LICENSE file.
//  https://github.com/ashima/webgl-noise
//
float noise(vec2 v) {

    // Precompute values for skewed triangular grid
    const vec4 C = vec4(0.211324865405187,
                        // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,
                        // 0.5*(sqrt(3.0)-1.0)
                        -0.577350269189626,
                        // -1.0 + 2.0 * C.x
                        0.024390243902439);
                        // 1.0 / 41.0

    // First corner (x0)
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);

    // Other two corners (x1, x2)
    vec2 i1 = vec2(0.0);
    i1 = (x0.x > x0.y)? vec2(1.0, 0.0):vec2(0.0, 1.0);
    vec2 x1 = x0.xy + C.xx - i1;
    vec2 x2 = x0.xy + C.zz;

    // Do some permutations to avoid
    // truncation effects in permutation
    i = mod289(i);
    vec3 p = permute(
            permute( i.y + vec3(0.0, i1.y, 1.0))
                + i.x + vec3(0.0, i1.x, 1.0 ));

    vec3 m = max(0.5 - vec3(
                        dot(x0,x0),
                        dot(x1,x1),
                        dot(x2,x2)
                        ), 0.0);

    m = m*m ;
    m = m*m ;

    // Gradients:
    //  41 pts uniformly over a line, mapped onto a diamond
    //  The ring size 17*17 = 289 is close to a multiple
    //      of 41 (41*7 = 287)

    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;

    // Normalise gradients implicitly by scaling m
    // Approximation of: m *= inversesqrt(a0*a0 + h*h);
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0+h*h);

    // Compute final noise value at P
    vec3 g = vec3(0.0);
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * vec2(x1.x,x2.x) + h.yz * vec2(x1.y,x2.y);
    return 130.0 * dot(m, g);
}

// x should be in [0,1] and 'cut' should be in [0,1).
float cutTransform(float x, float cut){
	// map x from [0,cut]+[cut,1] to 0+[0,1]
	x = (x-cut)/(1.0-cut); 
	x = max( x ,0.0);
	x = (1.0-cos(${PI}*x))*0.5;
	return x;
}

float starCoef(vec2 v, float x){
	return cutTransform(noise((750.1325+v)*120.0)+x*0.05,0.8);
}

void main() {
	vec2 v = gl_FragCoord.xy/u_resolution.y;
	v/=u_density;
	v.y = 1.0-v.y;

	v.x += u_seed;

	// separate to sky and water
	bool sky = true;
	if (v.y>=0.5) {
		v.y = 1.0-v.y;
		sky = false;
	}

	// ----------------- create galaxies -----------------
	float t = (noise(v*2.0)*0.7+noise((50.0+v)*4.0)*0.3);
	vec3 mainGalaxy = t * vec3(0.2, 0.8, 0.8);

	float s = 0.0;
	// only add details in the sky.
	if (sky)
		s = 1.5*noise((v+100.0)*8.0);
	vec3 detailGalaxy = s * vec3(0.04, 0.12, 0.12);

	// ----------------- create stars -----------------
	// The value of u below will be close to 1 in a point like pattern.
	// We also help the stars shine a little bit where the galaxies are.
	float u = starCoef(v, s+t);

	if (!sky){	
		//In the water, make the star seem more faded and large by taking the average of a small neighborhood
		float dd = 1.0/u_resolution.y;
		u +=  starCoef(v+vec2(0,dd),s+t) +
					starCoef(v+vec2(0,-dd),s+t) +
					starCoef(v+vec2(dd,0),s+t) +
					starCoef(v+vec2(-dd,0),s+t) +
					starCoef(v+vec2(dd,dd),s+t) +
					starCoef(v+vec2(dd,-dd),s+t) +
					starCoef(v+vec2(-dd,dd),s+t) +
					starCoef(v+vec2(-dd,-dd),s+t);
		u/=7.0; // dividing only by 7 to keep the shining.
	}
	vec3 starColor = u*vec3(0.3, 1.0, 1.0);

	// ----------------- water affect -----------------
	// The details on the water affect should increase as we are getting closer to the horizon (y=0.5).
	// horizonCoef = 0 when close by and 1 near the horizon, and grows like a z^4.
	float horizonCoef = (v.y*2.0)*(v.y*2.0)*(v.y*2.0)*(v.y*2.0); 
	float waterCoef = noise(
													vec2(1231.24, 3535.4) + // just some "random" seed
													v*vec2(0.5, 10.0*horizonCoef) + // more details the closer we are to the horizon.
													+3.0*vec2(cos(u_time),(1.0+horizonCoef)*(1.0+cos(u_seed+u_time)*0.5)));
	vec3 water = waterCoef*vec3(0.1,0.3,0.3);
	if (sky)
		water *=0.0;

	float opacity = 1.0;
	float blueConstant = 0.18;

	/*if (!sky){
		opacity = (1.0-2.0*v.y);
		blueConstant = 0.22;
	}*/

	gl_FragColor = vec4(mainGalaxy+detailGalaxy+starColor+water,0.0)
								+vec4(0.0, 0.0, blueConstant, opacity);

}

`

